    void showIntro(int step){
        introStep=Math.max(0,Math.min(2,step));
        String[] titles={"Make every introduction count.","One tap. A lasting connection.","Your team, beautifully connected."};
        String[] descriptions={"Create a digital card, choose an approved template and share it with a link or QR code. Your recipient needs no app.","Administrators can prepare, write and verify reusable NFC cards. Reassign a card when your team changes, without replacing it.","Members manage permitted details on the go. Administrators keep branding consistent and review consented leads and activity. Your plan and role determine access."};
        LinearLayout box=page(titles[introStep],"MEET HUDDLE · "+(introStep+1)+" OF 3","intro");bottom.setVisibility(View.GONE);
        LinearLayout visual=section(box,"");visual.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(255,244,207),BLUSH}));visual.setPadding(dp(24),dp(28),dp(24),dp(28));
        TextView mark=text(visual,new String[]{"h*","↗","◎"}[introStep],64);mark.setTextColor(GREEN);mark.setTypeface(Typeface.create("sans-serif-black",Typeface.NORMAL));
        text(visual,new String[]{"Your card. Your introduction.","Share, write, verify, reuse.","People first. Always."}[introStep],21).setTypeface(null,Typeface.BOLD);
        caption(visual,descriptions[introStep]);
        LinearLayout dots=new LinearLayout(this);dots.setGravity(Gravity.CENTER);box.addView(dots,new LinearLayout.LayoutParams(-1,dp(48)));
        for(int i=0;i<3;i++){final int page=i;TextView dot=new TextView(this);dot.setText(i==introStep?"●":"○");dot.setTextColor(GREEN);dot.setTextSize(23);dot.setGravity(Gravity.CENTER);dot.setContentDescription("Introduction page "+(i+1));dot.setOnClickListener(v->showIntro(page));dots.addView(dot,new LinearLayout.LayoutParams(dp(48),dp(48)));}
        visual.setOnTouchListener(new View.OnTouchListener(){float x;public boolean onTouch(View v,android.view.MotionEvent e){if(e.getAction()==android.view.MotionEvent.ACTION_DOWN){x=e.getX();return true;}if(e.getAction()==android.view.MotionEvent.ACTION_UP){float d=e.getX()-x;if(Math.abs(d)>dp(45))showIntro(introStep+(d<0?1:-1));else v.performClick();return true;}return true;}});
        button(box,introStep==2?"Let’s get started":"Next",v->{if(introStep==2)finishIntro();else showIntro(introStep+1);});
        if(introStep>0)secondary(box,"Back",v->showIntro(introStep-1));
        secondary(box,"Skip introduction",v->finishIntro());
        caption(box,"Digital first. Optional NFC. No recipient app needed.");
        if(android.animation.ValueAnimator.areAnimatorsEnabled()){content.setAlpha(0f);content.animate().alpha(1f).setDuration(180).start();}
    }
