    private void nav(String selected){bottom.removeAllViews();bottom.setVisibility(workspace==null?View.GONE:View.VISIBLE);boolean member=workspace!=null&&workspace.optJSONObject("user").optString("role").equals("member");String[] labels=member?new String[]{"Home","Manage"}:new String[]{"Home","Team","NFC","Manage"};String[] ids=member?new String[]{"home","settings"}:new String[]{"home","team","nfc","settings"};int[] imgs=new int[ids.length];for(int n=0;n<ids.length;n++)imgs[n]=getResources().getIdentifier("ic_nav_"+ids[n],"drawable",getPackageName());for(int i=0;i<ids.length;i++){final String id=ids[i];LinearLayout tab=new LinearLayout(this);tab.setOrientation(1);tab.setGravity(Gravity.CENTER);tab.setBackground(shape(id.equals(selected)?BLUSH:Color.WHITE,14));tab.setContentDescription(labels[i]);ImageView icon=new ImageView(this);icon.setImageResource(imgs[i]);icon.setImageTintList(android.content.res.ColorStateList.valueOf(id.equals(selected)?GREEN:MUTED));tab.addView(icon,new LinearLayout.LayoutParams(dp(23),dp(23)));TextView label=new TextView(this);label.setText(labels[i]);label.setGravity(Gravity.CENTER);label.setTextSize(11);label.setTextColor(id.equals(selected)?GREEN:MUTED);label.setPadding(0,dp(4),0,0);tab.addView(label);tab.setOnClickListener(v->{if(id.equals("home"))showHome();else if(id.equals("team"))showTeam();else if(id.equals("nfc"))showWriter();else showSettings();});bottom.addView(tab,new LinearLayout.LayoutParams(0,dp(58),1));}}
    boolean current(int request){return request==epoch&&!isFinishing()&&!isDestroyed();}
    private String checkedOrigin(String input)throws Exception{
        URI u=new URI(input.trim());String host=u.getHost(),scheme=u.getScheme();if(host==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||!(u.getPath().isEmpty()||u.getPath().equals("/")))throw new Exception("Enter a server address without a path.");
        boolean lan=host.matches("192\\.168\\.\\d{1,3}\\.\\d{1,3}")||host.matches("10\\.\\d{1,3}\\.\\d{1,3}\\.\\d{1,3}")||host.matches("172\\.(1[6-9]|2\\d|3[01])\\.\\d{1,3}\\.\\d{1,3}")||host.equals("localhost")||host.equals("127.0.0.1");
        if(!"https".equals(scheme)&&!("http".equals(scheme)&&lan))throw new Exception("Use HTTPS, or a private-network HTTP address for testing.");return new URI(scheme,null,host,u.getPort(),null,null,null).toString();
    }
    void serverDialog(){disarm();LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(22),dp(8),dp(22),dp(8));caption(box,"Enter your company server address. For a local test, your phone and laptop must be on a reachable Wi-Fi network.");EditText input=field(box,"Server address",origin,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);input.setHint("https://cards.company.com");AlertDialog d=new AlertDialog.Builder(this).setTitle("Connect your workspace").setView(box).setPositiveButton("Connect",null).setNegativeButton("Cancel",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{String next=checkedOrigin(input.getText().toString());if(!next.equals(origin)){sessionCookie="";workspace=null;SessionStore.clear(this);getPreferences(0).edit().remove("pending_registration").apply();}origin=next;getPreferences(0).edit().putString("origin",origin).apply();d.dismiss();connect();}catch(Exception e){input.setError(e.getMessage());}}));d.show();}
    void connect(){LinearLayout box=page("A good connection starts here.","Opening your workspace securely…","home");ProgressBar progress=new ProgressBar(this);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(GREEN));progress.setContentDescription("Loading workspace");box.addView(progress,new LinearLayout.LayoutParams(dp(42),dp(42)));int request=epoch;worker.execute(()->{try{JSONObject result=api("/api/state","GET",null);ui.post(()->{if(current(request)){workspace=result;showHome();}});}catch(Exception e){ui.post(()->{if(!current(request))return;if(e instanceof ApiError&&((ApiError)e).code==401)showLogin("");else if(e instanceof ApiError&&((ApiError)e).code==403)showLogin(e.getMessage());else{LinearLayout error=page("Cannot connect","Your sign-in has not been checked because the server could not be reached.","home");caption(error,connectionMessage(e));button(error,"Try again",v->connect());secondary(error,"Change server",v->serverDialog());}});}});}
    private void showLogin(String message){workspace=null;LinearLayout box=page("Welcome back","Sign in to manage your team’s digital cards.","login");LinearLayout card=section(box,"Company sign-in");EditText email=field(card,"Email address","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS),password=field(card,"Password","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setTransformationMethod(android.text.method.PasswordTransformationMethod.getInstance());TextView error=caption(card,message);Button login=button(card,"Sign in",v->{});login.setOnClickListener(v->{login.setEnabled(false);error.setText("Signing in…");final String address=email.getText().toString().trim(),secret=password.getText().toString();int request=epoch;worker.execute(()->{try{JSONObject auth=api("/api/login","POST",new JSONObject().put("email",address).put("password",secret));ui.post(()->{if(current(request)){password.setText("");if(auth.optBoolean("mfa_required")){login.setEnabled(true);admin().verifyChallenge(auth,()->connect());}else connect();}});}catch(Exception e){ui.post(()->{if(current(request)){login.setEnabled(true);error.setText(e instanceof ApiError?e.getMessage():connectionMessage(e));}});}});});caption(box,origin.isEmpty()?"Connect to your company server to begin.":"Server: "+origin);secondary(box,"Change server",v->serverDialog());secondary(box,"Create an organization",v->admin().register());caption(box,"Recipients view cards in their browser. They do not need this app.");}
    JSONArray team(){return workspace==null?new JSONArray():workspace.optJSONArray("team");}
    String division(String id){if(workspace!=null){JSONArray divisions=workspace.optJSONArray("divisions");for(int i=0;divisions!=null&&i<divisions.length();i++){JSONObject d=divisions.optJSONObject(i);if(d.optString("id").equals(id))return d.optString("name");}}return id;}
    void showHome(){if(workspace==null){connect();return;}if(workspace.optJSONObject("user").optString("role").equals("member")){admin().memberHome();return;}JSONObject user=workspace.optJSONObject("user"),company=workspace.optJSONObject("company");LinearLayout box=page("Hello, "+user.optString("name").split(" ")[0]+".",company.optString("name")+" · "+user.optString("role"),"home");button(box,"My card",v->admin().myCard());LinearLayout overview=section(box,"Your team, connected");int active=0;JSONArray staff=team();for(int i=0;staff!=null&&i<staff.length();i++)if(staff.optJSONObject(i).optInt("active")==1)active++;TextView count=text(overview,String.valueOf(active),40);count.setTypeface(null,Typeface.BOLD);caption(overview,"Active members in your administrator scope");button(overview,"Manage team",v->showTeam());LinearLayout cards=section(box,"Ready for the next introduction");caption(cards,"Choose a teammate, prepare their link and write a physical NFC card. Recipients only need a browser.");button(cards,"Set up an NFC card",v->showWriter());secondary(box,"Refresh workspace",v->connect());secondary(box,"Manage organization",v->admin().manage());secondary(box,"Switch organization",v->admin().organizations());}
    void showTeam(){if(workspace==null){connect();return;}LinearLayout box=page("Your team","Find a colleague and keep their card up to date.","team");EditText search=field(box,"Search team","",InputType.TYPE_CLASS_TEXT);search.setHint("Name or email");LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);box.addView(rows);Runnable draw=()->{rows.removeAllViews();String query=search.getText().toString().toLowerCase(Locale.ROOT);JSONArray staff=team();int count=0;for(int i=0;staff!=null&&i<staff.length();i++){JSONObject person=staff.optJSONObject(i);if(person.optInt("active")!=1||!(person.optString("name")+person.optString("email")).toLowerCase(Locale.ROOT).contains(query))continue;count++;LinearLayout card=section(rows,person.optString("name"));caption(card,person.optString("title")+" · "+division(person.optString("division_id")));caption(card,person.optString("email"));card.setClickable(true);card.setFocusable(true);card.setContentDescription("Edit "+person.optString("name"));card.setOnClickListener(v->showMember(person));}if(count==0)caption(rows,"No matching team members.");};draw.run();search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){draw.run();}public void afterTextChanged(Editable e){}});}
