    boolean trusted(String url){try{String declared=workspace==null?origin:workspace.optString("base_url",origin);URI a=new URI(checkedOrigin(declared)),b=new URI(url);return b.getUserInfo()==null&&b.getFragment()==null&&Objects.equals(a.getScheme(),b.getScheme())&&Objects.equals(a.getHost(),b.getHost())&&a.getPort()==b.getPort();}catch(Exception e){return false;}}
